      next_action: "Deliver Speed-to-Lead ROI calculator link",
      next_action_date: new Date().toISOString().split('T')[0]
    }
  }
];

const profile = $('STATE — Founder Profile').first().json;
const yesterday = $('STATE — Yesterday Scorecard').first().json;
const jobs = $('STATE — Jobs Due').all().map(i => i.json);
const prospects = $('STATE — Prospects Due').all().map(i => i.json);
const learning = $('STATE — Learning Queue').first().json;

const warnings = [];

if ((yesterday.unjustified_model_switches || 0) >= 2) {
  warnings.push('Tool/model switching exceeded operating tolerance yesterday.');
}

if ((yesterday.business_outreach || 0) < profile.business_outreach_floor) {
  warnings.push('Business development floor was missed yesterday.');
}

if (!yesterday.build_proof_completed) {
  warnings.push('Yesterday did not produce a completed technical proof point.');
}

const today = new Date().toISOString().split('T')[0];

return [{
  json: {
    date: today,
    income: {
      floor: profile.income_floor_monthly,
      comfort_target: `${profile.income_comfort_low}-${profile.income_comfort_high}`
    },
    career: {
      daily_floor: profile.job_action_floor,
      due_actions: jobs
    },
    sales: {
      new_outreach_floor: profile.business_outreach_floor,
      followup_floor: profile.followup_floor,
      followups_due: prospects
    },
    learning: {
      concept: learning.concept
    },
    performance: {
      yesterday_score: yesterday.daily_score,
      warnings: warnings
    },
    deep_work_capacity: `${profile.deep_work_min_hours}-${profile.deep_work_max_hours} hours`
  }
}];

const packet = $('CODE — Daily Requirements Engine & Merge Packet').first().json;
let rawResponse = $json.text || $json.response || $json;

let brief = null;
try {
  if (typeof rawResponse === 'string') {
    // Strip markdown code fences if present
    const clean = rawResponse.replace(/```json/g, '').replace(/```/g, '').trim();
    brief = JSON.parse(clean);
  } else {
    brief = rawResponse;
  }
} catch (e) {
  brief = null;
}

// Deterministic Fallback if model fails or outputs invalid format
if (!brief || !brief.primary_outcome || !Array.isArray(brief.career_plan) || !Array.isArray(brief.revenue_plan)) {
  brief = {
    primary_outcome: "Generate commercial opportunities and execute career obligations before discretionary building.",
    career_plan: [
      `${packet.career.daily_floor} targeted enterprise career actions`,
      `${packet.career.due_actions.length} scheduled recruiter follow-ups`
    ],
    revenue_plan: [
      `${packet.sales.new_outreach_floor} fresh contractor outreach touches`,
      `${packet.sales.followups_due.length} active prospect follow-ups`
    ],
    learning_focus: packet.learning.concept,
    build_focus: "Complete verification receipt for Publishing Control Plane.",
    deep_work_plan: {
      career_minutes: 90,
      sales_minutes: 60,
      build_minutes: 90
    },
    do_not_do: "Unnecessary tool/model switching or speculative new project setup.",
    reasoning_summary: packet.performance.warnings.join(' ') || "Execution baseline enforcement.",
    is_fallback: true
  };
}

// Format Slack message blocks
const slackText = `*PENN FOUNDER OS — MORNING COMMAND*

*PRIMARY OUTCOME*
${brief.primary_outcome}

*CAREER*
• ${packet.career.daily_floor} serious career actions required
• ${packet.career.due_actions.length} existing follow-ups due

*REVENUE*
• ${packet.sales.new_outreach_floor} qualified new contacts required
• ${packet.sales.followups_due.length} prospect follow-ups due

*LEARNING*
${brief.learning_focus}

*BUILD*
${brief.build_focus}

*DEEP WORK*
${brief.deep_work_plan.career_minutes}m Career | ${brief.deep_work_plan.sales_minutes}m Sales | ${brief.deep_work_plan.build_minutes}m Build

*GUARDRAIL*
No unnecessary model switching.

*DO NOT WORK ON*
${brief.do_not_do}

──────────────────────────────────────
*Keymon:* What is your #1 commitment for today?`;

return [{
  json: {
    brief: brief,
    slack_formatted_message: slackText,
    warnings: packet.performance.warnings
  }
}];

const response = $json.response || $json.text || "";
const isValid = response.trim().length >= 15;

return [{
  json: {
    date: new Date().toISOString().split('T')[0],
    primary_commitment: response.trim(),
    is_valid_commitment: isValid,
    committed_at: new Date().toISOString(),
    status: isValid ? "active" : "flagged_insufficient",
    morning_brief_sent: true,
    commitment_received: true
  }
}];

const commitment = $json;
// Persist locally or append to log/receipt
return [{
  json: {
    ...commitment,
    contract_sealed: true,
    receipt_path: `operations/receipts/${commitment.date}_receipt_founder_os_morning_commitment.json`
  }
}];
